function studioFinishedSeedOverlay(requestRecord, clips, nativeReady) {
  const kind = studioFinishedOriginKind(requestRecord);
  if (!kind) return {};
  const firstUrl = String(clips[0]?.url || "").trim() || null;
  const az = studioIsAzFinishedVideo(requestRecord);
  const note = az
    ? `origin=az-finished-video; ez-input=${kind}. Finished passthrough. Skip P1/voiceover/R2-R5. Generate the grid thumbnail (prefer gold / black-and-gold sophisticated lettering ~80%; colorful 3D only occasionally). AI may write the post caption only; do not burn text onto the finished file. az-auto-queue=1.`
    : `origin=ez-wizard; ez-input=${kind}. Finished passthrough. Skip P1/voiceover/R2-R5. Generate the grid thumbnail (prefer gold / black-and-gold sophisticated lettering ~80%; colorful 3D only occasionally). AI may write the post caption only; do not burn text onto the finished file.`;
  if (kind === "finished-video") {
    return {
      Output_Status: firstUrl ? "Ready for Review" : "In Production",
      Render_Status: firstUrl ? "Rendered" : null,
      Final_File_URL: firstUrl,
      Studio_Preview_URL: firstUrl,
      Publish_Asset_URL: firstUrl && item4UrlIsPublicPublishCdn(firstUrl) ? firstUrl : null,
      Asset_Need_Status: "Not Needed",
      Asset_Selection_Status: null,
      Composition_ID: null,
      Output_Notes: note,
    };
  }
  return {
    Output_Status: nativeReady || clips.length ? "Ready for Review" : "In Production",
    Render_Status: clips.length ? "Native Photo Route" : null,
    Asset_Need_Status: "Not Needed",
    Output_Notes: note,
  };
}

const STUDIO_SIMILAR_WATCHLIST_SETTING = "SIMILAR_ACCOUNT_WATCHLIST";

function studioIndustryBestWindows(platform, outputType) {
  const p = String(platform || "").toLowerCase();
  const t = String(outputType || "").toLowerCase();
  if (p.includes("tiktok")) return { days: ["Mon", "Tue", "Wed", "Thu", "Fri"], windows: ["19:00-21:00"], label: "TikTok weekday evenings" };
  if (p.includes("youtube") && (t.includes("standard") || t.includes("long"))) return { days: ["Mon", "Tue", "Wed", "Thu", "Fri"], windows: ["10:00-16:00"], label: "YouTube standard weekday daytime" };
  if (p.includes("youtube")) return { days: ["Wed", "Thu", "Fri", "Sat"], windows: ["14:00-16:00", "20:00-22:00"], label: "YouTube Short afternoon/evening" };
  if (t.includes("story")) return { days: ["Mon", "Tue", "Wed", "Thu", "Fri"], windows: ["16:00-18:00", "19:00-21:00"], label: "Stories late afternoon/evening" };
  if (t.includes("carousel") || t.includes("single") || t.includes("feed") || t.includes("multi-image") || t.includes("photo")) {
    return { days: ["Wed", "Thu"], windows: ["12:00-14:00", "18:00-20:00"], label: "Feed/carousel midday or evening" };
  }
  if (p.includes("facebook")) return { days: ["Tue", "Wed", "Thu"], windows: ["12:00-13:00", "18:00-20:00"], label: "Facebook Reel lunch/evening" };
  return { days: ["Tue", "Wed", "Thu"], windows: ["11:00-13:00", "18:00-21:00"], label: "Reel midday or evening" };
}

function studioChicagoDateTimeParts(date = new Date()) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Chicago",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  }).formatToParts(date);
  const get = (type) => Number(parts.find((part) => part.type === type)?.value);
  return {
    year: get("year"),
    month: get("month"),
    day: get("day"),
    hour: get("hour"),
    minute: get("minute"),
  };
}

function studioChicagoWallToUtcMs(year, month, day, hour, minute) {
  const want = Date.UTC(year, month - 1, day, hour, minute, 0, 0);
  let ms = want;
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Chicago",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  });
  for (let i = 0; i < 8; i++) {
    const parts = fmt.formatToParts(new Date(ms));
    const get = (type) => Number(parts.find((part) => part.type === type)?.value);
    const got = Date.UTC(get("year"), get("month") - 1, get("day"), get("hour"), get("minute"), 0, 0);
    const delta = want - got;
    if (delta === 0) return ms;
    ms += delta;
  }
  return ms;
}

function studioAddCivilDays(year, month, day, delta) {
  const utc = Date.UTC(year, month - 1, day) + delta * 86400000;
  const next = new Date(utc);
  return { year: next.getUTCFullYear(), month: next.getUTCMonth() + 1, day: next.getUTCDate() };
}

function studioSuggestedLocalDatetime(windows, now = new Date()) {
  const first = String(windows?.[0] || "12:00-13:00");
  const start = first.split("-")[0] || "12:00";
  const [hh, mm] = start.split(":").map((n) => Number(n) || 0);
  const chicago = studioChicagoDateTimeParts(now);
  let civil = { year: chicago.year, month: chicago.month, day: chicago.day };
  let ms = studioChicagoWallToUtcMs(civil.year, civil.month, civil.day, hh, mm || 0);
  if (ms <= now.getTime() + 10 * 60 * 1000) {
    civil = studioAddCivilDays(civil.year, civil.month, civil.day, 1);
    ms = studioChicagoWallToUtcMs(civil.year, civil.month, civil.day, hh, mm || 0);
  }
  return new Date(ms).toISOString();
}

function studioScheduleStoryRank(outputType) {
  return /story/i.test(String(outputType || "")) ? 1 : 0;
}

function studioScheduleOverridesFromPayload(payload) {
  const overrides = new Map();
  const schedules = payload?.schedules && typeof payload.schedules === "object" && !Array.isArray(payload.schedules)
    ? payload.schedules
    : {};
  for (const [key, value] of Object.entries(schedules)) {
    const iso = String(value || "").trim();
    if (!key || !iso || Number.isNaN(Date.parse(iso))) continue;
    overrides.set(String(key), new Date(iso).toISOString());
  }
  return overrides;
}

function studioBuildSuggestedScheduleMap(items, occupiedByPlatform = {}, now = new Date()) {
  const reserved = {};
  for (const [platform, times] of Object.entries(occupiedByPlatform || {})) {
    reserved[platform] = [...(times || [])];
  }
  const indexed = (items || []).map((item, index) => ({ item, index }));
  indexed.sort((a, b) => {
    const rank = studioScheduleStoryRank(a.item.output_type) - studioScheduleStoryRank(b.item.output_type);
    return rank || a.index - b.index;
  });
  const stamps = new Map();
  for (const { item } of indexed) {
    const platform = String(item.platform || "").trim();
    const outputType = String(item.output_type || "").trim();
    if (!platform || !outputType) continue;
    const key = `${platform}::${outputType}`;
    const existing = String(item.scheduled_at || "").trim();
    if (existing && !Number.isNaN(Date.parse(existing))) {
      const iso = new Date(existing).toISOString();
      stamps.set(key, iso);
      (reserved[platform] ||= []).push(Date.parse(iso));
      continue;
    }
    const industry = studioIndustryBestWindows(platform, outputType);
    const suggested = studioSuggestedLocalDatetime(industry.windows, now);
    const iso = studioNextOpenScheduleIso(suggested, reserved[platform] || []);
    stamps.set(key, iso);
    (reserved[platform] ||= []).push(Date.parse(iso));
  }
  return stamps;
}

async function studioOccupiedSchedulesOrEmpty(env) {
  try {
    return await studioLoadOccupiedSchedules(env);
  } catch (error) {
    console.warn("suggested schedule occupancy read failed", error);
    return {};
  }
}

function studioDestinationScheduleStamp(current, key, stamps, overrides) {
  const iso = stamps.get(key);
  if (!iso) return null;
  const currentIso = current ? String(f(current, "Scheduled_At") || "").trim() : "";
  if (currentIso && !(overrides instanceof Map && overrides.has(key))) return null;
  return iso;
}

