  r.Clip_1_URL = '{{if(1.Studio_Source_Authority_Status = "Ready"; 1.Studio_Source_Clip_1_URL; "")}}';
  r.Clip_2_URL = '{{if(1.Studio_Source_Authority_Status = "Ready"; 1.Studio_Source_Clip_2_URL; "")}}';
