  const jobs = [
    { id: 5893683, key: "P020-2", table: PHASE6_CAROUSEL_SLIDES_TABLE, formula: 'AND({Slide_Voiceover_Status}="Ready",{Deleted From Carousel}=0,{Slide_Voiceover_Text}!="",{Slide_Voice_ID}!="",{Studio_Voice_Prep_Request_ID}!="")' },
  ];
